    s = data[2]

    # dp[i][j] represents the minimum number of Guernsey-majority or tied districts 
    # for first i pastures with last district ending at position j
    dp = [[float('inf')] * N for _ in range(N + 1)]
    dp[0][0] = 0

    def count_guernseys(start, end):
        return s[start:end].count('G')

    # Precompute all possible segments up to K length
    valid_segments = []
    for i in range(N):
        for j in range(i + 1, min(i + K + 1, N + 1)):
            segment = s[i:j]
            g_count = segment.count('G')
            h_count = len(segment) - g_count
            if g_count >= h_count:
                valid_segments.append((i, j))

    # Dynamic Programming approach
    for i in range(1, N + 1):
        for j in range(i):
            if dp[i-1][j] < float('inf'):
                # Try placing a district ending at position i-1 (0-indexed)
                start = j
                end = i
                if end - start <= K:
                    g_count = s[start:end].count('G')
                    h_count = len(s[start:end]) - g_count
                    if g_count >= h_count:
                        dp[i][end] = min(dp[i][end], dp[i-1][j])
                    else:
                        dp[i][end] = min(dp[i][end], dp[i-1][j] + 1)

    # Find minimum among all valid final states
    result = float('inf')
    for i in range(N):
        if dp[N][i] < float('inf'):
            result = min(result, dp[N][i])

    print(result)

